{"command":"python3 - << 'PY'
import os, pty, subprocess, sys, time, select

def run(stdin_is_tty=False, stdout_is_tty=False, stderr_is_tty=False, env_extra={}, inp=b"hello\n--- PASS: TestFoo (0.00s)\n", args=["testfilter"]):
    masters={}
    slaves={}
    def make_tty(name):
        m,s = pty.openpty()
        masters[name]=m; slaves[name]=s
    if stdin_is_tty: make_tty('stdin')
    if stdout_is_tty: make_tty('stdout')
    if stderr_is_tty: make_tty('stderr')
    # stdin
    stdin_fd = slaves['stdin'] if stdin_is_tty else subprocess.PIPE
    stdout_fd = slaves['stdout'] if stdout_is_tty else subprocess.PIPE
    stderr_fd = slaves['stderr'] if stderr_is_tty else subprocess.PIPE
    env=dict(os.environ); env.update(env_extra)
    # ensure FORCE not present unless set
    if "RICHGO_FORCE_COLOR" not in env_extra:
        env.pop("RICHGO_FORCE_COLOR",None)
    p=subprocess.Popen(["/workspace/executable"]+args, stdin=stdin_fd, stdout=stdout_fd, stderr=stderr_fd, env=env, cwd="/tmp", close_fds=True)
    # close slaves in parent
    for s in slaves.values(): os.close(s)
    out_data=b""; err_data=b""
    if stdin_is_tty:
        os.write(masters['stdin'], inp)
        os.close(masters['stdin']); del masters['stdin']
    else:
        p.stdin.write(inp); p.stdin.close()
    # read ttys
    if stdout_is_tty:
        # read until eof
        while True:
            try:
                chunk=os.read(masters['stdout'], 4096)
            except OSError:
                break
            if not chunk: break
            out_data+=chunk
        os.close(masters['stdout'])
    else:
        out_data=p.stdout.read()
    if stderr_is_tty:
        while True:
            try:
                chunk=os.read(masters['stderr'], 4096)
            except OSError:
                break
            if not chunk: break
            err_data+=chunk
        os.close(masters['stderr'])
    else:
        if stderr_fd==subprocess.PIPE:
            err_data=p.stderr.read()
    rc=p.wait()
    return out_data, err_data, rc

for combo in [(False,False,False),(False,True,False),(True,False,False),(False,False,True),(True,True,True)]:
    out,err,rc=run(*[bool(x) for x in []], stdin_is_tty=combo[0], stdout_is_tty=combo[1], stderr_is_tty=combo[2])
    print(f"stdinTTY={combo[0]} stdoutTTY={combo[1]} stderrTTY={combo[2]} rc={rc} out={out!r} err={err!r}")
PY
"}

