    def make(name):
        m,s=pty.openpty(); masters[name]=m; slaves[name]=s
    if stdin_is_tty: make('stdin')
    if stdout_is_tty: make('stdout')
    if stderr_is_tty: make('stderr')
    stdin_fd = slaves['stdin'] if stdin_is_tty else subprocess.PIPE
    stdout_fd = slaves['stdout'] if stdout_is_tty else subprocess.PIPE
    stderr_fd = slaves['stderr'] if stderr_is_tty else subprocess.PIPE
