    for s in list(slaves.values()): os.close(s)
    # write stdin
    try:
        if stdin_is_tty:
            os.write(masters['stdin'], inp)
            # give some time then close?
            import time; time.sleep(0.3)
            os.close(masters['stdin']); del masters['stdin']
        else:
            p.stdin.write(inp); p.stdin.close()
    except Exception as e:
        print(" write err", e)
    out_data=b""; err_data=b""
    if stdout_is_tty:
        try:
            while True:
                chunk=os.read(masters['stdout'], 4096)
                if not chunk: break
                out_data+=chunk
        except OSError: pass
        try: os.close(masters['stdout'])
        except: pass
    else:
        out_data=p.stdout.read()
    if stderr_is_tty:
        try:
            while True:
                chunk=os.read(masters['stderr'], 4096)
                if not chunk: break
                err_data+=chunk
        except OSError: pass
        try: os.close(masters['stderr'])
        except: pass
    else:
        err_data=p.stderr.read() if stderr_fd==subprocess.PIPE else b"<not pipe>"
    rc=p.wait()
    return out_data, err_data, rc

