import pty, subprocess, os, time
def test(stdin_tty, stdout_tty, stderr_tty, use_ctrl_d=True):
    masters={}
    slaves={}
    def make(name):
        m,s=pty.openpty(); masters[name]=m; slaves[name]=s
    if stdin_tty: make('in')
    if stdout_tty: make('out')
    if stderr_tty: make('err')
    env=dict(os.environ); env.pop("RICHGO_FORCE_COLOR",None)
    p=subprocess.Popen(["/workspace/executable","testfilter"],
        stdin=slaves.get('in', subprocess.PIPE),
        stdout=slaves.get('out', subprocess.PIPE),
        stderr=slaves.get('err', subprocess.PIPE),
        env=env, cwd="/tmp")
    for s in slaves.values(): os.close(s)
    if stdin_tty:
        os.write(masters['in'], b"hello\n--- PASS: TestFoo (0.00s)\n")
        time.sleep(0.2)
        if use_ctrl_d:
            os.write(masters['in'], b"\x04")
        else:
            pass
    else:
        p.stdin.write(b"hello\n--- PASS: TestFoo (0.00s)\n"); p.stdin.close()
    out=b""; err=b""
    # read
    try:
        if stdout_tty:
            while True:
                c=os.read(masters['out'],4096)
                if not c: break
                out+=c
        else:
            out=p.stdout.read()
    except OSError as e:
        out+=f"<read err {e}>".encode()
    try:
        if stderr_tty:
            while True:
                c=os.read(masters['err'],4096)
                if not c: break
                err+=c
        else:
            err=p.stderr.read()
    except OSError as e:
        err+=f"<read err {e}>".encode()
    rc=p.wait()
    if stdin_tty:
        try: os.close(masters['in'])
        except: pass
    print(f"inTTY={stdin_tty} outTTY={stdout_tty} errTTY={stderr_tty} rc={rc} out={out!r} err={err!r}")

test(True, False, True, True)
test(True, True, True, True)
test(False, False, True, True)
test(True, False, False, True)
PY
