for force in [True,False]:
    env=dict(os.environ); env["PATH"]="/tmp/fakebin:/usr/bin:/bin"
    if force: env["RICHGO_FORCE_COLOR"]="1"
    p=subprocess.Popen(["/workspace/executable","testfilter"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, cwd="/tmp")
    p.stdin.write(b"x\n"); p.stdin.close(); start=time.time()
    while p.poll() is None:
        r,_,_=select.select([p.stdout,p.stderr],[],[],0.05)
        for f in r:
            d=os.read(f.fileno(),4096)
            if d: print(force, f"{time.time()-start:.3f}", "out" if f==p.stdout else "err", d)
    # drain
    for f in [p.stdout,p.stderr]:
        d=f.read()
        if d: print(force, "final", f, d)
    print("done", force, p.returncode)
