// parseYAML parses the small subset of YAML needed for .richstyle files:
// block/flow mappings and sequences, plain/single/double quoted scalars,
// comments and null values. Syntax errors are reported in the style of a
// YAML parser.
func parseYAML(data string) (*yamlNode, error) {
	data = strings.TrimPrefix(data, "\ufeff")
	rawLines := strings.Split(data, "\n")
	var lines []yamlLine
	for i, raw := range rawLines {
		raw = strings.TrimSuffix(raw, "\r")
		// Strip comments that occupy their own line; other comment
		// handling is done when scalars are consumed.
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if trimmed == "---" || trimmed == "..." {
			continue
		}
		indent := 0
		for indent < len(raw) && raw[indent] == ' ' {
			indent++
		}
		content := raw[indent:]
		lines = append(lines, yamlLine{indent: indent, content: content, no: i + 1})
	}
	if len(lines) == 0 {
		return &yamlNode{kind: yamlNull, line: 1}, nil
	}
	p := &yamlParser{lines: lines}
	node, err := p.parseNode(lines[0].indent)
	if err != nil {
		return nil, err
	}
	return node, nil
}

func (p *yamlParser) parseNode(indent int) (*yamlNode, error) {
	if p.pos >= len(p.lines) {
		return &yamlNode{kind: yamlNull}, nil
	}
	line := p.lines[p.pos]
	content := line.content
	if content == "-" || strings.HasPrefix(content, "- ") {
		return p.parseSequence(indent)
	}
	if strings.HasPrefix(content, "[") || strings.HasPrefix(content, "{") {
		node, err := parseInlineNode(content, line.no)
		if err != nil {
			return nil, err
		}
		p.pos++
		return node, nil
	}
	if _, _, ok := splitMappingKey(content); ok {
		return p.parseMapping(indent)
	}
	// A single scalar document.
	node, err := parseInlineNode(content, line.no)
	if err != nil {
		return nil, err
	}
	p.pos++
	return node, nil
}

func (p *yamlParser) parseMapping(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlMapping, line: p.lines[p.pos].no}
	for p.pos < len(p.lines) {
		line := p.lines[p.pos]
		if line.indent < indent {
			break
		}
		if line.indent > indent {
			return nil, syntaxErr(line.no, "mapping values are not allowed in this context")
		}
		if line.content == "-" || strings.HasPrefix(line.content, "- ") {
			break
		}
		keyText, rest, ok := splitMappingKey(line.content)
		if !ok {
			return nil, syntaxErr(line.no, "could not find expected ':'")
		}
		keyNode, err := parseInlineScalarToken(keyText, line.no)
		if err != nil {
			return nil, err
		}
		p.pos++
		restTrim := strings.TrimSpace(rest)
		var val *yamlNode
		switch {
		case restTrim == "|" || restTrim == ">" || strings.HasPrefix(restTrim, "|") && len(restTrim) <= 3 || strings.HasPrefix(restTrim, ">") && len(restTrim) <= 3:
			// Block scalar.
			val = p.consumeBlockScalar(restTrim, indent, line.no)
		case restTrim != "" && !strings.HasPrefix(restTrim, "#"):
			v, err := parseInlineNode(restTrim, line.no)
			if err != nil {
				return nil, err
			}
			val = v
		default:
			// Value is a nested block, a block sequence at the
			// same indent, or null.
			if p.pos < len(p.lines) {
				next := p.lines[p.pos]
				if next.indent > indent {
					v, err := p.parseNode(next.indent)
					if err != nil {
						return nil, err
					}
					val = v
				} else if next.indent == indent && (next.content == "-" || strings.HasPrefix(next.content, "- ")) {
					v, err := p.parseSequence(indent)
					if err != nil {
						return nil, err
					}
					val = v
				}
			}
			if val == nil {
				val = &yamlNode{kind: yamlNull, line: line.no}
			}
		}
		node.pairs = append(node.pairs, yamlPair{key: keyNode, val: val})
	}
	return node, nil
}

func (p *yamlParser) consumeBlockScalar(marker string, parentIndent, lineNo int) *yamlNode {
	var parts []string
	baseIndent := -1
	for p.pos < len(p.lines) {
		line := p.lines[p.pos]
		if line.indent <= parentIndent {
			break
		}
		if baseIndent < 0 {
			baseIndent = line.indent
		}
		text := strings.Repeat(" ", line.indent-baseIndent) + line.content
		parts = append(parts, text)
		p.pos++
	}
	var value string
	if strings.HasPrefix(marker, ">") {
		value = strings.Join(parts, " ")
	} else {
		value = strings.Join(parts, "\n")
	}
	return &yamlNode{kind: yamlScalar, value: value, line: lineNo}
}

func (p *yamlParser) parseSequence(indent int) (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, line: p.lines[p.pos].no}
	for p.pos < len(p.lines) {
		line := p.lines[p.pos]
		if line.indent != indent || !(line.content == "-" || strings.HasPrefix(line.content, "- ")) {
			break
		}
		rest := ""
		if line.content != "-" {
			rest = strings.TrimSpace(line.content[2:])
		}
		p.pos++
		var val *yamlNode
		switch {
		case rest == "":
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				v, err := p.parseNode(p.lines[p.pos].indent)
				if err != nil {
					return nil, err
				}
				val = v
			} else {
				val = &yamlNode{kind: yamlNull, line: line.no}
			}
		case isMappingStart(rest):
			// "- key: value" form; mainly relevant for skipping
			// unknown structured values.
			v, err := parseSyntheticMapping(rest, line.no)
			if err != nil {
				return nil, err
			}
			// Additional, more-indented mapping lines belong to
			// the same item.
			for p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				extra, err := p.parseMapping(p.lines[p.pos].indent)
				if err != nil {
					return nil, err
				}
				v.pairs = append(v.pairs, extra.pairs...)
			}
			val = v
		default:
			v, err := parseInlineNode(rest, line.no)
			if err != nil {
				return nil, err
			}
			val = v
		}
		node.elems = append(node.elems, val)
	}
	return node, nil
}

func parseSyntheticMapping(content string, lineNo int) (*yamlNode, error) {
	keyText, rest, ok := splitMappingKey(content)
	if !ok {
		return nil, syntaxErr(lineNo, "could not find expected ':'")
	}
	key, err := parseInlineScalarToken(keyText, lineNo)
	if err != nil {
		return nil, err
	}
	var val *yamlNode
	if strings.TrimSpace(rest) == "" {
		val = &yamlNode{kind: yamlNull, line: lineNo}
	} else {
		v, err := parseInlineNode(strings.TrimSpace(rest), lineNo)
		if err != nil {
			return nil, err
		}
		val = v
	}
	return &yamlNode{kind: yamlMapping, line: lineNo, pairs: []yamlPair{{key: key, val: val}}}, nil
}

func isMappingStart(s string) bool {
	_, _, ok := splitMappingKey(s)
	return ok
}

// splitMappingKey finds "key:" at the start of a block mapping line. The
// colon must be followed by a blank or the end of the line.
func splitMappingKey(s string) (key, rest string, ok bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", "", false
	}
	if s[0] == '\'' || s[0] == '"' {
		// Quoted key: consume the quote, then expect a colon.
		end, err := quotedEnd(s, 0)
		if err != nil {
			return "", "", false
		}
		j := end
		for j < len(s) && (s[j] == ' ' || s[j] == '\t') {
			j++
		}
		if j < len(s) && s[j] == ':' && (j+1 == len(s) || s[j+1] == ' ' || s[j+1] == '\t') {
			return s[:end], s[j+1:], true
		}
		return "", "", false
	}
	for i := 0; i < len(s); i++ {
		if s[i] == ':' && (i+1 == len(s) || s[i+1] == ' ' || s[i+1] == '\t') {
			if i == 0 {
				return "", "", false
			}
			return strings.TrimSpace(s[:i]), s[i+1:], true
		}
	}
	return "", "", false
}

func parseInlineScalarToken(s string, lineNo int) (*yamlNode, error) {
	node, err := parseInlineNode(strings.TrimSpace(s), lineNo)
	if err != nil {
		return nil, err
	}
	return node, nil
}

// parseInlineNode parses a value occupying (part of) a single line: flow
// collections, quoted scalars and plain scalars.
func parseInlineNode(s string, lineNo int) (*yamlNode, error) {
	s = strings.TrimSpace(s)
	if s == "" || strings.HasPrefix(s, "#") {
		return &yamlNode{kind: yamlNull, line: lineNo}, nil
	}
	cur := &flowCursor{s: s, line: lineNo}
	node, err := cur.parseValue()
	if err != nil {
		return nil, err
	}
	if node != nil {
		node.line = lineNo
	}
	return node, nil
}

type flowCursor struct {
	s    string
	pos  int
	line int
}

func (c *flowCursor) skipSpaces() {
	for c.pos < len(c.s) && (c.s[c.pos] == ' ' || c.s[c.pos] == '\t') {
		c.pos++
	}
}

func (c *flowCursor) parseValue() (*yamlNode, error) {
	c.skipSpaces()
	if c.pos >= len(c.s) {
		return &yamlNode{kind: yamlNull, line: c.line}, nil
	}
	switch c.s[c.pos] {
	case '[':
		return c.parseFlowSeq()
	case '{':
		return c.parseFlowMap()
	case '\'':
		str, err := c.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		return &yamlNode{kind: yamlScalar, value: str, quoted: true, line: c.line}, nil
	case '"':
		str, err := c.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		return &yamlNode{kind: yamlScalar, value: str, quoted: true, line: c.line}, nil
	default:
		// Plain scalar: consume until a flow delimiter. Colons
		// are handled by the flow map parser, which calls us
		// with plainKey handling before this point.
		start := c.pos
		depth := 0
		for c.pos < len(c.s) {
			ch := c.s[c.pos]
			if depth == 0 && (ch == ',' || ch == ']' || ch == '}') {
				break
			}
			if ch == '[' || ch == '{' {
				depth++
			}
			if ch == ']' || ch == '}' {
				depth--
			}
			c.pos++
		}
		text := strings.TrimSpace(c.s[start:c.pos])
		text = stripPlainComment(text)
		return &yamlNode{kind: yamlScalar, value: text, line: c.line}, nil
	}
}

func stripPlainComment(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '#' && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
			return strings.TrimSpace(s[:i])
		}
	}
	return s
}

func (c *flowCursor) parseFlowSeq() (*yamlNode, error) {
	node := &yamlNode{kind: yamlSequence, line: c.line}
	c.pos++ // consume '['
	for {
		c.skipSpaces()
		if c.pos >= len(c.s) {
			return nil, syntaxErr(c.line, "did not find expected ',' or ']'")
		}
		if c.s[c.pos] == ']' {
			c.pos++
			return node, nil
		}
		elem, err := c.parseValue()
		if err != nil {
			return nil, err
		}
		node.elems = append(node.elems, elem)
		c.skipSpaces()
		if c.pos >= len(c.s) {
			return nil, syntaxErr(c.line, "did not find expected ',' or ']'")
		}
		if c.s[c.pos] == ',' {
			c.pos++
			continue
		}
		if c.s[c.pos] == ']' {
			c.pos++
			return node, nil
		}
		return nil, syntaxErr(c.line, "did not find expected ',' or ']'")
	}
}

func (c *flowCursor) parseFlowMap() (*yamlNode, error) {
	node := &yamlNode{kind: yamlMapping, line: c.line}
	c.pos++ // consume '{'
	for {
		c.skipSpaces()
		if c.pos >= len(c.s) {
			return nil, syntaxErr(c.line, "did not find expected ',' or '}'")
		}
		if c.s[c.pos] == '}' {
			c.pos++
			return node, nil
		}
		// Key: either quoted or a plain key ending at ':'.
		var key *yamlNode
		if c.s[c.pos] == '\'' || c.s[c.pos] == '"' {
			k, err := c.parseValue()
			if err != nil {
				return nil, err
			}
			key = k
		} else {
			start := c.pos
			for c.pos < len(c.s) && c.s[c.pos] != ':' && c.s[c.pos] != ',' && c.s[c.pos] != '}' {
				c.pos++
			}
			key = &yamlNode{kind: yamlScalar, value: strings.TrimSpace(c.s[start:c.pos]), line: c.line}
		}
		c.skipSpaces()
		if c.pos >= len(c.s) || c.s[c.pos] != ':' {
			return nil, syntaxErr(c.line, "did not find expected ':'")
		}
		c.pos++
		val, err := c.parseValue()
		if err != nil {
			return nil, err
		}
		node.pairs = append(node.pairs, yamlPair{key: key, val: val})
		c.skipSpaces()
		if c.pos >= len(c.s) {
			return nil, syntaxErr(c.line, "did not find expected ',' or '}'")
		}
		if c.s[c.pos] == ',' {
			c.pos++
			continue
		}
		if c.s[c.pos] == '}' {
			c.pos++
			return node, nil
		}
		return nil, syntaxErr(c.line, "did not find expected ',' or '}'")
	}
}

func quotedEnd(s string, start int) (int, error) {
	cur := &flowCursor{s: s, pos: start}
	if s[start] == '\'' {
		_, err := cur.parseSingleQuoted()
		return cur.pos, err
	}
	_, err := cur.parseDoubleQuoted()
	return cur.pos, err
}

func (c *flowCursor) parseSingleQuoted() (string, error) {
	// s[pos] == '\''
	c.pos++
	var b strings.Builder
	for c.pos < len(c.s) {
		ch := c.s[c.pos]
		if ch == '\'' {
			if c.pos+1 < len(c.s) && c.s[c.pos+1] == '\'' {
				b.WriteByte('\'')
				c.pos += 2
				continue
			}
			c.pos++
			return b.String(), nil
		}
		b.WriteByte(ch)
		c.pos++
	}
	return "", syntaxErr(c.line, "found unexpected end of stream")
}

func (c *flowCursor) parseDoubleQuoted() (string, error) {
	c.pos++
	var b strings.Builder
	for c.pos < len(c.s) {
		ch := c.s[c.pos]
		if ch == '"' {
			c.pos++
			return b.String(), nil
		}
		if ch == '\\' && c.pos+1 < len(c.s) {
			n := c.s[c.pos+1]
			switch n {
			case 'n':
				b.WriteByte('\n')
				c.pos += 2
			case 't':
				b.WriteByte('\t')
				c.pos += 2
			case 'r':
				b.WriteByte('\r')
				c.pos += 2
			case '0':
				b.WriteByte(0)
				c.pos += 2
			case '\\':
				b.WriteByte('\\')
				c.pos += 2
			case '"':
				b.WriteByte('"')
				c.pos += 2
			case 'x', 'u', 'U':
				digits := 2
				if n == 'u' {
					digits = 4
				} else if n == 'U' {
					digits = 8
				}
				if c.pos+2+digits <= len(c.s) {
					if v, err := strconv.ParseUint(c.s[c.pos+2:c.pos+2+digits], 16, 32); err == nil {
						b.WriteRune(rune(v))
						c.pos += 2 + digits
						continue
					}
				}
				b.WriteByte(n)
				c.pos += 2
			default:
				b.WriteByte(n)
				c.pos += 2
			}
			continue
		}
		b.WriteByte(ch)
		c.pos++
	}
	return "", syntaxErr(c.line, "found unexpected end of stream")
}

// YAML tag resolution helpers.
func yamlTag(n *yamlNode) string {
	switch n.kind {
	case yamlMapping:
		return "!!map"
	case yamlSequence:
		return "!!seq"
	case yamlNull:
		return "!!null"
	}
	if n.quoted {
		return "!!str"
	}
	if isYAMLNull(n.value) {
		return "!!null"
	}
	if _, ok := yamlBoolValue(n.value); ok {
		return "!!bool"
	}
	if isYAMLIntLiteral(n.value) {
		return "!!int"
	}
	if isYAMLFloatLiteral(n.value) {
		return "!!float"
	}
	return "!!str"
}

func isYAMLNull(s string) bool {
	switch s {
	case "", "~", "null", "Null", "NULL":
		return true
	}
	return false
}

func yamlBoolValue(s string) (bool, bool) {
	switch s {
	case "y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON":
		return true, true
	case "n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF":
		return false, true
	}
	return false, false
}

func isYAMLIntLiteral(s string) bool {
	if s == "" {
		return false
	}
	// Decimal (allowing underscores as in YAML), hex, octal and binary.
	body := s
	if body[0] == '+' || body[0] == '-' {
		body = body[1:]
	}
	if body == "" {
		return false
	}
	if strings.HasPrefix(body, "0x") || strings.HasPrefix(body, "0X") {
		_, err := strconv.ParseUint(body[2:], 16, 64)
		return err == nil
	}
	if strings.HasPrefix(body, "0o") || strings.HasPrefix(body, "0O") {
		_, err := strconv.ParseUint(body[2:], 8, 64)
		return err == nil
	}
	if strings.HasPrefix(body, "0b") || strings.HasPrefix(body, "0B") {
		_, err := strconv.ParseUint(body[2:], 2, 64)
		return err == nil
	}
	for _, r := range strings.ReplaceAll(body, "_", "") {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

func isYAMLFloatLiteral(s string) bool {
	if s == "" {
		return false
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		// A plain integer is an int, not a float.
		return !isYAMLIntLiteral(s)
	}
	switch s {
	case ".inf", ".Inf", ".INF", "-.inf", "-.Inf", "-.INF", "+.inf", "+.Inf", "+.INF", ".nan", ".Nan", ".NAN":
		return true
	}
	return false
}

// parseYAMLIntValue converts a plain numeric scalar into an int, mimicking
// YAML decoding into an int field (floats are truncated toward zero).
func parseYAMLIntValue(s string) (int, bool) {
	body := s
	sign := int64(1)
	if strings.HasPrefix(body, "+") {
		body = body[1:]
	} else if strings.HasPrefix(body, "-") {
		sign = -1
		body = body[1:]
	}
	if strings.HasPrefix(body, "0x") || strings.HasPrefix(body, "0X") {
		if v, err := strconv.ParseInt(body[2:], 16, 64); err == nil {
			return int(sign * v), true
		}
		return 0, false
	}
	if strings.HasPrefix(body, "0o") || strings.HasPrefix(body, "0O") {
		if v, err := strconv.ParseInt(body[2:], 8, 64); err == nil {
			return int(sign * v), true
		}
		return 0, false
	}
	if strings.HasPrefix(body, "0b") || strings.HasPrefix(body, "0B") {
		if v, err := strconv.ParseInt(body[2:], 2, 64); err == nil {
			return int(sign * v), true
		}
		return 0, false
	}
	if len(body) > 1 && body[0] == '0' {
		// Leading zero: octal when all digits are 0-7.
		octal := true
		for _, r := range body {
			if r < '0' || r > '7' {
				octal = false
				break
			}
		}
		if octal {
			if v, err := strconv.ParseInt(body, 8, 64); err == nil {
				return int(sign * v), true
			}
		}
	}
	if v, err := strconv.ParseInt(strings.ReplaceAll(s, "_", ""), 10, 64); err == nil {
		return int(v), true
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return int(f), true
	}
	return 0, false
}

func typeErrorString(line int, node *yamlNode, target string) string {
	tag := yamlTag(node)
	if node.kind == yamlScalar {
		return fmt.Sprintf("  line %d: cannot unmarshal %s `%s` into %s", line, tag, node.value, target)
	}
	return fmt.Sprintf("  line %d: cannot unmarshal %s into %s", line, tag, target)
}
