		if v.kind == yamlNull {
			continue
		}
		switch key {
		case "hide", "bold", "faint", "italic", "underline", "blinkSlow", "blinkRapid",
			"inverse", "conceal", "crossOut", "frame", "encircle", "overline":
			b, ok := decodeBool(v, terrs)
			if !ok {
				continue
			}
			setStyleBool(style, key, b)
		case "foreground", "background":
			if v.kind != yamlScalar {
				terrs.add(v.line, v, "string")
				continue
			}
			color, err := parseColor(v.value)
			if err != nil {
				return errInvalidColorFormat
			}
			if key == "foreground" {
				style.Foreground = color
			} else {
				style.Background = color
			}
		default:
			// Unknown style fields are ignored.
		}
	}
	return nil
}

func setStyleBool(style *Style, key string, b bool) {
	switch key {
	case "hide":
		style.Hide = b
	case "bold":
		style.Bold = b
	case "faint":
		style.Faint = b
	case "italic":
		style.Italic = b
	case "underline":
		style.Underline = b
	case "blinkSlow":
		style.BlinkSlow = b
	case "blinkRapid":
		style.BlinkRapid = b
	case "inverse":
		style.Inverse = b
	case "conceal":
		style.Conceal = b
	case "crossOut":
		style.CrossOut = b
	case "frame":
		style.Frame = b
	case "encircle":
		style.Encircle = b
	case "overline":
		style.Overline = b
	}
}

func decodeBool(v *yamlNode, terrs *collectedTypeErrors) (bool, bool) {
	if v.kind != yamlScalar || v.quoted {
		terrs.add(v.line, v, "bool")
		return false, false
	}
	if b, ok := yamlBoolValue(v.value); ok {
		return b, true
	}
	terrs.add(v.line, v, "bool")
	return false, false
}

func decodeInt(v *yamlNode, terrs *collectedTypeErrors) (int, bool) {
	if v.kind != yamlScalar || v.quoted {
		terrs.add(v.line, v, "int")
		return 0, false
	}
	if _, isBool := yamlBoolValue(v.value); isBool {
		terrs.add(v.line, v, "int")
		return 0, false
	}
	if n, ok := parseYAMLIntValue(v.value); ok {
		return n, true
	}
	terrs.add(v.line, v, "int")
	return 0, false
}

