	core := parsed.style.formatWith(p.labelPrefixFor(parsed) + highlighted)
	removed := p.applyRemovals(core)
	if strings.TrimSpace(removed) == "" {
		return nil
	}
	if parsed.special {
		return []byte(removed)
	}
	return []byte(removed + "\n")
}

