func (p *lineParser) parse(line string) parsedLine {
	cfg := p.cfg

	// Bare PASS / FAIL package lines.
	if m := bareRe.FindStringSubmatch(line); m != nil {
		if m[1] == "PASS" {
			return parsedLine{kind: kindBarePass, style: &cfg.PassPackageStyle, content: "PASS", bare: true}
		}
		return parsedLine{kind: kindBareFail, style: &cfg.FailPackageStyle, content: "FAIL", bare: true}
	}

	// Build lines.
	if m := buildBracketRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindBuild, style: &cfg.BuildStyle, label: "BUILD", content: m[1] + " " + m[2], updateState: true}
	}
	if m := buildSingleRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindBuild, style: &cfg.BuildStyle, label: "BUILD", content: m[1] + "\n", updateState: true, special: true}
	}

