	if strings.HasPrefix(line, "=== RUN   Test") {
		rest := line[len("=== RUN   Test"):]
		content := rest
		if cfg.LeaveTestPrefix {
			content = "Test" + rest
		}
		content = indentBySlash(content)
		return parsedLine{kind: kindStart, style: &cfg.StartStyle, label: "START", content: content, updateState: true}
	}

