	if m := testResultRe.FindStringSubmatch(line); m != nil {
		result := m[1]
		var style *Style
		var label string
		var kind lineKind
		switch result {
		case "PASS":
			style, label, kind = &cfg.PassStyle, "PASS", kindPass
		case "FAIL":
			style, label, kind = &cfg.FailStyle, "FAIL", kindFail
		default:
			style, label, kind = &cfg.SkipStyle, "SKIP", kindSkip
		}
		prefix := "--- " + result + ": Test"
		trimmed := strings.TrimLeft(line, " ")
		var content string
		if strings.HasPrefix(trimmed, prefix) {
			rest := trimmed[len(prefix):]
			content = rest
			if cfg.LeaveTestPrefix {
				content = "Test" + rest
			}
		} else {
			content = trimmed
		}
		content = indentBySlash(content)
		return parsedLine{kind: kind, style: style, label: label, content: content, updateState: true}
	}

