	if parsed, ok := p.parseOk(line); ok {
		return parsed
	}

	// Package fail lines.
	if m := failPackageRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindFail, style: &cfg.FailStyle, label: "FAIL", content: m[1], updateState: true}
	}

	// Package skip lines ("? ... [no test files]").
	if m := skipPackageRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindSkip, style: &cfg.SkipStyle, label: "SKIP", content: m[1], updateState: true}
	}

	// Coverage lines.
	if m := coverRe.FindStringSubmatch(line); m != nil {
		value, _ := strconv.ParseFloat(m[1], 64)
		filled := int(value / 10)
		bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
