func (p *lineParser) parseOk(line string) (parsedLine, bool) {
	cfg := p.cfg
	if m := okCoverageRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " " + m[3], updateState: true}, true
