		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " ", updateState: true}, true
	}
	if m := okBracketRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " ", updateState: true}, true
	}
