		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + "\n ", updateState: true, special: true}, true
	}
	if okEmptyRe.MatchString(line) {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: "\n ", updateState: true, special: true}, true
	}
	return parsedLine{}, false
}
