	skipPackageRe  = regexp.MustCompile(`^\?[ \t]+(\S+[ \t]+\[(?:no test files|no tests to run)\])$`)
	coverRe        = regexp.MustCompile(`^coverage: (\d+\.\d)% of statements$`)
	okCoverageRe   = regexp.MustCompile(`^ok[ \t]+(\S+)[ \t]+([\d.]+\w+|\(cached\))[ \t]+(coverage:[ \t]+\d+\.\d+% of statements)[ \t]*$`)
	okNoTestsRe    = regexp.MustCompile(`^ok[ \t]+(\S+)[ \t]+([\d.]+\w+|\(cached\))[ \t]+\[no tests to run\]$`)
	okSimpleRe     = regexp.MustCompile(`^ok[ \t]+(\S+)[ \t]+([\d.]+\w+|\(cached\))[ \t]*$`)
	okBracketRe    = regexp.MustCompile(`^ok[ \t]+(\S+)[ \t]+\[no tests to run\]$`)
	okBareRe       = regexp.MustCompile(`^ok[ \t]+(\S+)$`)
	okEmptyRe      = regexp.MustCompile(`^ok[ \t]+$`)
)

type lineParser struct {
	cfg       *Config
	removals  []*regexp.Regexp
	state     *Style
	zeroState Style
}

func newLineParser(cfg *Config) *lineParser {
	p := &lineParser{cfg: cfg}
	p.state = &p.zeroState
	for _, pattern := range cfg.Removals {
		p.removals = append(p.removals, regexp.MustCompile(pattern))
	}
	return p
}

func (p *lineParser) applyRemovals(s string) string {
	for _, re := range p.removals {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

func (p *lineParser) labelPrefix(label string) string {
	switch p.cfg.LabelType {
	case "long":
		for len(label) < 5 {
			label += " "
		}
		return label + "| "
	case "short":
		short := shortLabel(label)
		for len(short) < 2 {
			short += " "
		}
		return short + " "
	default:
		return ""
	}
}

func shortLabel(label string) string {
	switch label {
	case "BUILD":
		return "!!"
	case "START":
		return ">"
	case "PASS":
		return "o"
	case "FAIL":
		return "x"
	case "SKIP":
		return "-"
	case "COVER":
		return "%"
	default:
		return ""
	}
}

func (p *lineParser) highlight(content string, prev *Style) string {
	return fileLineRe.ReplaceAllStringFunc(content, func(match string) string {
		sub := fileLineRe.FindStringSubmatch(match)
		if sub == nil {
			return match
		}
		return p.cfg.FileStyle.formatWith(sub[1]) + p.cfg.LineStyle.formatWith(sub[2]) + prev.startCodes()
	})
}

// processLine formats one logical line (without its trailing newline).
// It returns the bytes to write, or nil for no output.
func (p *lineParser) processLine(line string) []byte {
	if line == "" {
		return nil
	}
	parsed := p.parse(line)
	prev := p.state
	if parsed.updateState {
		p.state = parsed.style
	}

	if parsed.kind == kindGeneric {
		if prev.Hide {
			return nil
		}
		highlighted := p.highlight(parsed.content, prev)
		removed := p.applyRemovals(highlighted)
		if removed == "" {
			return nil
		}
		out := prev.formatWith(p.labelPrefix("") + removed)
		if strings.TrimSpace(out) == "" {
			return nil
		}
		return []byte(out + "\n")
	}

	// Classified lines.
	if parsed.style.Hide {
		return nil
	}
	highlighted := p.highlight(parsed.content, prev)
	core := parsed.style.formatWith(p.labelPrefixFor(parsed) + highlighted)
	removed := p.applyRemovals(core)
	if strings.TrimSpace(removed) == "" {
		return nil
	}
	if parsed.special {
		return []byte(removed)
	}
	return []byte(removed + "\n")
}

func (p *lineParser) labelPrefixFor(parsed parsedLine) string {
	if parsed.bare {
		return ""
	}
	return p.labelPrefix(parsed.label)
}

func (p *lineParser) parse(line string) parsedLine {
	cfg := p.cfg

	// Bare PASS / FAIL package lines.
	if m := bareRe.FindStringSubmatch(line); m != nil {
		if m[1] == "PASS" {
			return parsedLine{kind: kindBarePass, style: &cfg.PassPackageStyle, content: "PASS", bare: true}
		}
		return parsedLine{kind: kindBareFail, style: &cfg.FailPackageStyle, content: "FAIL", bare: true}
	}

	// Build lines.
	if m := buildBracketRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindBuild, style: &cfg.BuildStyle, label: "BUILD", content: m[1] + " " + m[2], updateState: true}
	}
	if m := buildSingleRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindBuild, style: &cfg.BuildStyle, label: "BUILD", content: m[1] + "\n", updateState: true, special: true}
	}

	// Test start lines.
	if strings.HasPrefix(line, "=== RUN   Test") {
		rest := line[len("=== RUN   Test"):]
		content := rest
		if cfg.LeaveTestPrefix {
			content = "Test" + rest
		}
		content = indentBySlash(content)
		return parsedLine{kind: kindStart, style: &cfg.StartStyle, label: "START", content: content, updateState: true}
	}

	// Test result lines.
	if m := testResultRe.FindStringSubmatch(line); m != nil {
		result := m[1]
		var style *Style
		var label string
		var kind lineKind
		switch result {
		case "PASS":
			style, label, kind = &cfg.PassStyle, "PASS", kindPass
		case "FAIL":
			style, label, kind = &cfg.FailStyle, "FAIL", kindFail
		default:
			style, label, kind = &cfg.SkipStyle, "SKIP", kindSkip
		}
		prefix := "--- " + result + ": Test"
		trimmed := strings.TrimLeft(line, " ")
		var content string
		if strings.HasPrefix(trimmed, prefix) {
			rest := trimmed[len(prefix):]
			content = rest
			if cfg.LeaveTestPrefix {
				content = "Test" + rest
			}
		} else {
			content = trimmed
		}
		content = indentBySlash(content)
		return parsedLine{kind: kind, style: style, label: label, content: content, updateState: true}
	}

	// Package pass lines ("ok ...").
	if parsed, ok := p.parseOk(line); ok {
		return parsed
	}

	// Package fail lines.
	if m := failPackageRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindFail, style: &cfg.FailStyle, label: "FAIL", content: m[1], updateState: true}
	}

	// Package skip lines ("? ... [no test files]").
	if m := skipPackageRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindSkip, style: &cfg.SkipStyle, label: "SKIP", content: m[1], updateState: true}
	}

	// Coverage lines.
	if m := coverRe.FindStringSubmatch(line); m != nil {
		value, _ := strconv.ParseFloat(m[1], 64)
		filled := int(value / 10)
		bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
		style := &cfg.UncoveredStyle
		if value >= float64(cfg.CoverThreshold) {
			style = &cfg.CoveredStyle
		}
		content := m[1] + "% [" + bar + "]"
		return parsedLine{kind: kindCover, style: style, label: "COVER", content: content}
	}

	// Anything else is passed through with the current style.
	return parsedLine{kind: kindGeneric, content: line}
}

func indentBySlash(content string) string {
	n := strings.Count(content, "/")
	if n == 0 {
		return content
	}
	return strings.Repeat("  ", n) + content
}

func (p *lineParser) parseOk(line string) (parsedLine, bool) {
	cfg := p.cfg
	if m := okCoverageRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " " + m[3], updateState: true}, true
	}
	if m := okNoTestsRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " ", updateState: true}, true
	}
	if m := okSimpleRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " ", updateState: true}, true
	}
	if m := okBracketRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + " ", updateState: true}, true
	}
	if m := okBareRe.FindStringSubmatch(line); m != nil {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: m[1] + "\n ", updateState: true, special: true}, true
	}
	if okEmptyRe.MatchString(line) {
		return parsedLine{kind: kindPass, style: &cfg.PassStyle, label: "PASS", content: "\n ", updateState: true, special: true}, true
	}
	return parsedLine{}, false
}
