import pty, subprocess, os, time

def run(binary, stdin_tty=False, stdout_tty=False, stderr_tty=False, env_extra={}, inp=b"hello\n--- PASS: TestFoo (0.00s)\n", args=["testfilter"]):
    masters={}; slaves={}
    def make(name):
        m,s=pty.openpty(); masters[name]=m; slaves[name]=s
    if stdin_tty: make('in')
    if stdout_tty: make('out')
    if stderr_tty: make('err')
    env=dict(os.environ); env.update(env_extra)
    env.pop("RICHGO_FORCE_COLOR",None)
    if "RICHGO_FORCE_COLOR" in env_extra: env.update(env_extra)
