		case '"', '\\'':
			quote = ch
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		}
	}
	return depth
}

func quoteUnclosed(s string) bool {
	var quote byte
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if quote == '"' {
